"""Build source-grounded L261-L265 incremental proof and dbt governance notes."""
from promote_l201_l205_notes import Lesson
from promote_l251_l270_common import run_batch

FD="src.book.reis-housley-fundamentals-data-engineering"; DD="src.book.kleppmann-ddia.1e"; DI="src.web.dbt-incremental-models"
DS="src.web.dbt-snapshots"; MC="src.web.dbt-model-contracts"; MV="src.web.dbt-model-versions"; DOC="src.web.dbt-documentation"; EX="src.web.dbt-exposures"
FDL="SRC-REIS-HOUSLEY-FUNDAMENTALS-DATA-ENGINEERING"; DDL="SRC-KLEPPMANN-DDIA-1E"; DIL="SRC-DBT-INCREMENTAL-MODELS"
DSL="SRC-DBT-SNAPSHOTS"; MCL="SRC-DBT-MODEL-CONTRACTS"; MVL="SRC-DBT-MODEL-VERSIONS"; DOCL="SRC-DBT-DOCUMENTATION"; EXL="SRC-DBT-EXPOSURES"

LESSONS=(
Lesson(261,"Lesson_261-the-seven-part-incremental-proof","The Seven Part Incremental Proof","149-seven-part-incremental-proof.md","wiki.transformation.seven-part-incremental-proof","Bảy phần bằng chứng nào đủ để bảo vệ claim rằng incremental model hội tụ với full recomputation trong phạm vi đã công bố?",(DI,DD,FD),(DIL,DDL,FDL),(
("1. Grain và identity","Viết một row output đại diện điều gì, key nào ổn định và NULL/duplicate được xử lý ra sao. Unique key trong config chỉ là input cho materialization; nó không chứng minh source slice unique. Proof có fixture làm key đổi, key trùng và same key different version. Nếu model chứa history, identity phải gồm valid-time/version thay vì entity key đơn. Không chốt grain thì mọi kiểm row count, merge và delete phía sau đều không có nghĩa."),
("2. Change capture boundary","Nêu field hoặc log position chọn changed population, ordering/tie rule, timezone, precision, lookback và retention. Chứng minh every relevant insert/update/delete xuất hiện hoặc liệt kê operation ngoài scope. `max(updated_at)` trên target không phải boundary nếu output timestamp bị transform. Source snapshot/interval và checkpoint được lưu typed, cùng schema/config version. Ca same timestamp ở boundary phải được replay hoặc tie-break deterministically."),
("3. Affected-state closure","Một changed row có thể làm thay đổi nhiều output rows qua joins, windows, aggregates hoặc dedup. Xác định closure từ changed inputs tới toàn bộ keys/partitions cần recompute. Với lifetime metric, closure có thể là customer chứ không phải order. Với rank/window, peer partition cần mở rộng. Proof dùng dependency examples để cho thấy filter sớm vẫn giữ đủ context, hoặc chọn partition rebuild khi delta algebra quá khó bảo vệ."),
("4. Mutation semantics","Lập bảng insert, in-place update, backdated correction, hard/soft delete, restore, duplicate delivery và schema/logic change. Mỗi mutation map tới append, update, invalidate, partition replace hoặc full refresh. Absence trong một incremental slice không phải delete. Logic change thường không phát event ở source nên cần migration/backfill decision riêng. Không được gọi model correct khi chỉ chứng minh append-only case trong khi source mutable."),
("5. Determinism và idempotency","Stable key, total ordering, canonical timezone/decimal/null và deterministic functions làm cùng logical input tạo cùng accepted state. Kill trước/sau merge, publication và checkpoint; rerun phải hội tụ. Audit/notification/hook cũng có operation identity. Nếu warehouse files hoặc timestamps khác nhưng consumer-visible rows tương đương, proof nêu observation boundary thay vì đòi byte identity không cần thiết."),
("6. Full-equivalence oracle","Tại fixed source boundary, build full result từ clean target rồi chạy incremental history dẫn tới cùng boundary. So schema, key set, typed row hash, delete/current-history state và business aggregates. Oracle không tái sử dụng incremental filter đang kiểm. Chạy nhiều mutation sequences và input orders. Mismatch được phân loại, không làm tròn hoặc bỏ qua bằng aggregate cao hơn. Periodic production reconciliation dùng cùng logic nhưng có cost/coverage statement."),
("7. Operability và reversal","Proof kết thúc bằng metrics: scanned input/target, affected rows, lateness beyond horizon, duplicate/collision, reconciliation residual, runtime/cost và full-refresh duration. Runbook nêu bootstrap, schema drift, checkpoint repair, backfill, rollback và when-to-full-refresh. Reversal trigger rõ: change fraction, mutation type, late horizon hoặc maintenance burden vượt threshold. Không có recovery owner thì design mới chỉ chạy được, chưa vận hành được."),
),tuple(f"Incremental-proof probe {i}: phần bằng chứng, counterexample, artifact locator và full-equivalence verdict phải rõ" for i in range(1,16))),
Lesson(262,"Lesson_262-the-incremental-failure-matrix","The Incremental Failure Matrix","150-incremental-failure-matrix.md","wiki.transformation.incremental-failure-matrix","Failure matrix nào bao phủ source, selection, compute, publication và recovery để một incremental model không che silent divergence?",(DI,DD),(DIL,DDL),(
("Matrix theo boundary","Hàng là failure: late/missing change, duplicate, schema shift, nondeterministic order, partial source, warehouse error, unknown commit, checkpoint drift, manual target edit. Cột là stage: discover/select, extract, transform, write, publish, checkpoint, observe/recover. Mỗi ô ghi detection, contained state, retry behavior, reconciliation và owner. Danh sách lỗi không có stage/state transition không giúp operator biết dữ liệu nào đang đáng tin."),
("Source và selection failures","Clock skew, unchanged cursor, expired retention, hard delete invisible và tie boundary tạo silent omission. Overlap chỉ chữa bounded lateness, không chữa delete vô hình. Detect bằng source lag, watermark age, deletion feed và fixed-boundary reconciliation. Khi checkpoint rơi ngoài retention, dừng incremental và bootstrap/backfill có kiểm soát; không nhảy checkpoint tới hiện tại để dashboard xanh."),
("Transform failures","Macro/config change, nondeterministic row_number, fanout, null key, window context thiếu và schema coercion có thể tạo output hợp lệ cú pháp nhưng sai. Compile/test chỉ bắt một phần. Mutation suite và full-equivalence oracle phải có ca mỗi lỗi. Quarantine same key different payload; không dùng arbitrary dedup. Changed logic cần impact range và backfill plan, vì source không phát lại lịch sử chỉ do code đổi."),
("Write và publication failures","Duplicate source keys làm merge fail hoặc chọn tùy engine; delete-insert crash có thể phơi gap; partition overwrite với incomplete slice xóa dữ liệu; commit outcome unknown dẫn tới retry blind. Build candidate, validate, atomic publish theo exact adapter guarantee và resolve outcome bằng transaction/query/publication ID. Target table tồn tại sau failure không chứng minh complete state. Giữ parent fingerprint để compare-and-set."),
("Checkpoint và side effects","Advance checkpoint trước durable publish gây gap; sau publish gây replay, nên design ưu tiên replay được hấp thụ. Artifact upload, audit row, notification và downstream trigger cũng cần state/identity. Một table đúng nhưng trigger chạy hai lần vẫn fail end-to-end idempotency. Persist run ledger with input boundary, code hash, candidate/publication ID, checkpoint before/after và disposition."),
("Game day scoring","Inject từng failure tại controlled kill point, dự báo state trước khi chạy rồi so observed. Chấm detection latency, blast radius, data divergence, recovery time, manual steps và evidence completeness. Stop rule bảo vệ source/shared warehouse. Rerun targeted scenario sau remediation. Matrix chỉ được đóng khi không có failure nào kết thúc bằng “operator đoán target hiện đang đúng”."),
),tuple(f"Incremental-failure probe {i}: injection point, durable state, alert, recovery và reconciliation phải nối được" for i in range(1,16))),
Lesson(263,"Lesson_263-snapshots-and-scd2-invariants","Snapshots and SCD2 Invariants","151-snapshots-scd2-invariants.md","wiki.transformation.snapshots-scd2-invariants","Snapshot SCD2 cần key, change strategy và temporal invariants nào để lịch sử không overlap, không mất delete và dùng được cho as-of joins?",(DS,DD),(DSL,DDL),(
("Snapshot quan sát state, không phải event log","Snapshot định kỳ so current mutable rows với version đã biết và ghi history kiểu SCD2. Nó chỉ thấy states tại các lần quan sát; hai thay đổi giữa runs có thể co lại thành một. Vì vậy snapshot không tái tạo mọi transaction và không thay CDC/audit log. Contract nêu cadence, source consistency và history fidelity cần thiết. Dùng snapshot cho dimension history, không gọi nó là event stream."),
("Unique key là entity identity","Key phải ổn định, unique và non-null trong source scope. Nếu business key tái sử dụng hoặc tenant scope thiếu, history của hai entity bị nối. Key change trông như delete plus insert, không phải rename tự hiểu. Test source uniqueness trước snapshot và lưu collision disposition. Surrogate snapshot record ID khác entity key; as-of join phải dùng entity key cộng valid interval."),
("Timestamp và check strategies","Timestamp strategy dựa reliable updated_at advancing on every relevant change; check strategy so configured fields. Timestamp thường dễ chịu hơn khi schema thêm cột nhưng bỏ sót change không cập nhật timestamp. Check all fields nhạy với schema/irrelevant changes; subset có thể bỏ semantic field. Strategy decision ghi producer guarantee, null behavior, precision và schema evolution. Không chọn bằng thói quen."),
("Valid-time invariants","Mỗi entity có intervals half-open `[valid_from, valid_to)`, tối đa một current row, không overlap và ordering deterministic. Adjacent gaps chỉ hợp lệ nếu entity thật sự absent và policy cho phép. As-of join dùng event time với interval, không current flag. Processing time của snapshot khác business-effective time; backdated source correction có thể cần custom handling/rebuild. Test exact boundary tại valid_to."),
("Hard deletes và invalidation","Current row biến mất khỏi source chỉ được biết nếu snapshot strategy/config xử lý hard delete và source observation đủ. Invalidate current version at detection time không cho biết actual delete time. Tombstone/new-record policy ảnh hưởng as-of consumers. Soft delete là field change và có restore. Retention/source filters có thể tạo false delete; snapshot query phải cover same universe every run."),
("SCD2 lab","Fixture gồm insert, two updates, same-timestamp tie, unchanged row, hard delete, soft delete/restore, key collision và schema add. Chạy repeated snapshots, inspect metadata columns và assert no overlap/one-current/as-of results. Reorder runs và fail midway. Compare with source change log oracle để nêu transitions snapshot không thể thấy. Đạt khi limitations được công bố, không chỉ table có nhiều rows."),
),tuple(f"Snapshot probe {i}: entity key, observed change, valid interval, delete state và as-of oracle phải rõ" for i in range(1,16))),
Lesson(264,"Lesson_264-model-contracts-versions-and-consumer-migration","Model Contracts Versions and Consumer Migration","152-model-contracts-versions-consumer-migration.md","wiki.transformation.model-contracts-versions-migration","Contract và model version phối hợp thế nào để bắt shape drift sớm nhưng vẫn cho consumer một migration window đo được?",(MC,MV,FD),(MCL,MVL,FDL),(
("Contract bảo vệ shape có giới hạn","Enforced model contract kiểm declared column names, data types và constraints được hỗ trợ trước/khi build theo tool/platform. Nó không chứng minh business meaning, completeness, freshness hay metric correctness. Constraint enforcement khác theo warehouse; một constraint có thể informational. Contract file và compiled DDL phải được review cùng adapter version. Không quảng bá contract thành data quality toàn diện."),
("Breaking change taxonomy","Remove/rename column, incompatible type/nullability, grain/key, meaning/unit/timezone, row filtering và SLA/access có thể phá consumer. Chỉ nhóm đầu dễ được shape contract bắt. Semantic change giữ schema y nguyên vẫn cần version/migration. Classify additive-compatible, behavior-compatible, deprecating và breaking theo consumer evidence. `select *` khiến additive column cũng có thể break output shape."),
("Khi nào version","Version model khi consumer ngoài quyền kiểm soát cần tiếp tục dùng old contract trong lúc migration; không version mọi refactor nội bộ. Nhiều live versions tăng compute/storage/docs/testing. Latest ref đổi theo maintainer; critical consumer có thể pin explicit version. Prerelease cho shadow validation. Version decision ghi expected lifetime, owner và sunset condition, tránh v1/v2 tồn tại vô hạn."),
("Migration window","Publish vNext beside current, build compatibility matrix, dual-run/reconcile representative periods và thông báo diff/deprecation date. Inventory consumers bằng refs, exposures, query history và owner confirmation; không coi lineage khai báo là đầy đủ. Consumer test, update và sign-off theo risk. Chuyển latest chỉ sau gates; old version tiếp tục monitored. Removal có explicit zero-usage/waiver evidence and rollback."),
("Compatibility adapters","Khi feasible, compatibility view hoặc alias giúp old schema map sang new, nhưng có expiry và tests. Không dùng shim để che meaning change không thể chuyển đổi. Backfill history, defaults và null mapping cần policy. Cross-version metrics được so cùng boundary. Access/grants và documentation thuộc migration, không chỉ SQL. Cost của serving both versions được đo."),
("Failure rehearsal","Inject undeclared column/type change để contract fail; inject semantic unit change để chứng minh shape contract vẫn pass. Deploy prerelease, pin one consumer, leave another on latest, then rollback latest pointer. Capture warnings, compiled artifacts, relations and consumer results. Đạt khi owner chứng minh migration/rollback without synchronized flag day và nêu phần contract không bắt được."),
),tuple(f"Contract-version probe {i}: change class, enforcement, consumer inventory, migration gate và rollback phải rõ" for i in range(1,16))),
Lesson(265,"Lesson_265-documentation-exposures-and-lineage-artifacts","Documentation Exposures and Lineage Artifacts","153-documentation-exposures-lineage-artifacts.md","wiki.transformation.documentation-exposures-lineage","Documentation, exposures và lineage artifacts cần kết hợp thế nào để người dùng tìm đúng owner, meaning, dependency và freshness thay vì chỉ xem một DAG đẹp?",(DOC,EX,FD),(DOCL,EXL,FDL),(
("Documentation là contract cho người đọc","Model/column/source descriptions nói grain, key, meaning, unit/timezone, update/delete behavior, freshness, limitations và owner. Docs block tái dùng long-form explanation nhưng không được biến thành copy chung vô nghĩa. Warehouse introspection có thể liệt kê cột chưa được mô tả; “xuất hiện trong docs” khác “được document”. Coverage check cần denominator và criticality, không chỉ phần trăm tổng."),
("Exposure nối tới consumption","Exposure mô tả dashboard, notebook, analysis, ML hay application downstream, cùng owner và declared dependencies. Nó giúp select/test ancestors và làm blast-radius visible. Manual exposure stale nếu owner không cập nhật; automatic exposure phụ thuộc integration/metadata coverage. URL/maturity không chứng minh usage hoặc correctness. So declared exposures với query/BI inventory và ghi unknown consumers."),
("Lineage có nhiều lớp","Graph lineage từ `ref`/`source` mô tả declared resource edges; compiled SQL/static analysis có thể bổ sung column lineage; warehouse query history thấy observed consumption. Dynamic SQL, external tools, copied tables và manual exports tạo gaps. Một DAG model-level không cho biết column meaning hay runtime freshness. Report lineage confidence/source và timestamp, không vẽ một đồ thị rồi gọi complete."),
("Artifact generation và freshness","Generated docs/artifacts thuộc exact project parse/compile/run and warehouse state. Pin invocation/version/target, publish immutable build or fingerprint, and refresh cadence. Stale docs nguy hiểm hơn no docs khi relation changed. CI checks missing descriptions, owners, tests/exposures and broken links; production job generates metadata after successful state. Secrets/PII samples không đi vào descriptions/artifacts."),
("Impact analysis","Khi column/model đổi, combine manifest parent/child edges, exposures, version refs, query history và owner confirmation. Rank critical consumers; absence from one source is not zero impact. Produce change dossier with affected nodes, unknowns, migration owners and evidence date. Test selection based lineage then validates representative downstream outputs. Documentation alone không thay consumer acceptance."),
("Retrieval lab","Đưa cho reviewer ba câu hỏi: dataset này có grain/owner gì; dashboard nào phụ thuộc; column đổi sẽ ảnh hưởng đâu. Họ chỉ dùng generated docs/artifacts and exposure inventory. Measure answer correctness/time and missing edges. Inject stale description, undeclared BI query and dynamic dependency. Đạt khi system signals uncertainty instead of confidently returning incomplete lineage."),
),tuple(f"Documentation probe {i}: retrieval question, metadata source, freshness, missing edge và owner evidence phải rõ" for i in range(1,16))),
)
QUERIES={261:["Seven-part incremental proof gồm gì?","Affected-state closure là gì?","Full-equivalence oracle thiết kế thế nào?"],262:["Incremental failure matrix có các boundary nào?","Unknown commit outcome xử lý ra sao?","Checkpoint failure tạo gap khi nào?"],263:["dbt snapshots khác CDC thế nào?","SCD2 invariants gồm gì?","Timestamp và check strategy khác nhau ra sao?"],264:["Model contract bảo vệ điều gì?","Khi nào nên version model?","Consumer migration window cần gate nào?"],265:["Exposure trong dbt dùng để làm gì?","Lineage artifact có giới hạn nào?","Kiểm documentation freshness thế nào?"]}
VERIFY={n:"Dùng project/fixture nhỏ có exact boundary và owner; capture source, compiled/runtime artifacts, relations và consumer-facing diff; đối soát bằng alternate computation hoặc inventory độc lập." for n in range(261,266)}
TAKEAWAYS={261:"Incremental correctness cần đủ grain, boundary, affected-state closure, mutations, determinism, full-equivalence và operability; thiếu một phần thì claim chỉ đúng trên happy path.",262:"Failure matrix phải nối lỗi với durable state, detection và recovery tại từng boundary; danh sách lỗi không cho operator biết dữ liệu hiện đáng tin đến đâu.",263:"Snapshot là sampled state history với SCD2 invariants, không phải transaction log; key, strategy, delete policy và as-of boundary quyết định độ tin cậy.",264:"Contract bắt shape trong phạm vi hỗ trợ, còn version tạo migration window cho breaking change; semantic compatibility vẫn cần consumer evidence.",265:"Documentation, exposure và lineage chỉ hữu ích khi có owner, freshness và confidence; một DAG đẹp không chứng minh dependency coverage hoàn chỉnh."}
